using OcctSharp.DocumentProjections;
using OcctSharp.LocalStepExports;
using OcctSharp.StepCafWorkspaces;
using OcctSharp.Tests.Shared;
namespace OcctSharp.Runtime.Tests;
public sealed class LocalStepExportTests {
 [Fact]public void NewBlGeometryNativeUnicodeSameNamePartsAndRepeatedInstancesActuallyRoundtrip()=>BatchBPLocalExportWorkflow.Run();
 static void WithSource(Action<string,StepCafReadResult,DocumentProjectionContext> action){string root=Path.Combine(Path.GetTempPath(),"OcctSharp.BP.Tests."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using var source=BatchBPLocalExportWorkflow.Source(root);using var context=DocumentProjectionContext.Bind(source.Document);action(root,source,context);}finally{Directory.Delete(root,true);}}
 [Fact]public void MultipleSelectedRootsRetainOneSharedDefinitionAcrossBothRoots()=>WithSource((root,source,context)=>{var labels=source.Diagnostics.FreeRoots.Select(x=>context.GetLabel(x.Entry)).ToArray();var result=LocalStepAssemblyExport.Export(context,labels,Path.Combine(root,"two"));Assert.Equal(2,result.Selected.Count);BatchBPLocalExportWorkflow.Verify(result,2,4);});
 [Fact]public void ForeignContextAndDuplicateLabelsAreRejectedBeforeOutputCreation()=>WithSource((root,source,context)=>{using var foreign=DocumentProjectionContext.Bind(source.Document);var selected=context.GetLabel(source.Diagnostics.FreeRoots[0].Entry);string target=Path.Combine(root,"foreign");Assert.Throws<ArgumentException>(()=>LocalStepAssemblyExport.Export(context,[foreign.GetLabel(selected.Entry)],target));Assert.Throws<ArgumentException>(()=>LocalStepAssemblyExport.Export(context,[selected,selected],target));Assert.False(Directory.Exists(target));});
 [Fact]public void EmptySelectionAndBudgetPlusOneLazySequenceAreRejected()=>WithSource((root,source,context)=>{string target=Path.Combine(root,"empty");Assert.Throws<ArgumentOutOfRangeException>(()=>LocalStepAssemblyExport.Export(context,[],target));int consumed=0;IEnumerable<DocumentProjectionLabel> Infinite(){while(true){++consumed;yield return context.GetLabel(source.Diagnostics.FreeRoots[0].Entry);}}Assert.Throws<ArgumentOutOfRangeException>(()=>LocalStepAssemblyExport.Export(context,Infinite(),target));Assert.Equal(129,consumed);Assert.False(Directory.Exists(target));});
 [Fact]public void ExistingDirectoryOrFileIsPreservedWithoutOverwrite()=>WithSource((root,source,context)=>{var selected=context.GetLabel(source.Diagnostics.FreeRoots[0].Entry);string directory=Path.Combine(root,"existing");Directory.CreateDirectory(directory);string file=Path.Combine(directory,"keep.txt");File.WriteAllText(file,"keep");Assert.Throws<IOException>(()=>LocalStepAssemblyExport.Export(context,[selected],directory));Assert.Throws<IOException>(()=>LocalStepAssemblyExport.Export(context,[selected],file));Assert.Equal("keep",File.ReadAllText(file));});
 [Fact]public void OpenCommandAndNonShapeLabelsAreRejectedWithoutPublishingDirectory()=>WithSource((root,source,context)=>{string target=Path.Combine(root,"command");var selected=context.GetLabel(source.Diagnostics.FreeRoots[0].Entry);source.Document.NewCommand();Assert.Throws<ArgumentException>(()=>LocalStepAssemblyExport.Export(context,[selected],target));source.Document.AbortCommand();Assert.Throws<ArgumentException>(()=>LocalStepAssemblyExport.Export(context,[context.GetLabel("0:1")],target));Assert.False(Directory.Exists(target));});
 [Theory][InlineData(-1)][InlineData(double.NaN)][InlineData(double.PositiveInfinity)][InlineData(.2)]public void InvalidPrivatePrecisionRejectsBeforeNativeTransfer(double precision)=>WithSource((root,source,context)=>{string target=Path.Combine(root,"invalid");Assert.Throws<ArgumentOutOfRangeException>(()=>LocalStepAssemblyExport.Export(context,[context.GetLabel(source.Diagnostics.FreeRoots[0].Entry)],target,new(Precision:precision)));Assert.False(Directory.Exists(target));});
 [Fact]public void FileMutationMissingOutputsAndExtraFilesInvalidateExportManifest()=>WithSource((root,source,context)=>{var selected=context.GetLabel(source.Diagnostics.FreeRoots[0].Entry);var output=LocalStepAssemblyExport.Export(context,[selected],Path.Combine(root,"mutated"));string path=Path.Combine(output.DirectoryPath,output.Files[1].FileName),text=File.ReadAllText(path);File.AppendAllText(path,"\n");Assert.Throws<IOException>(output.Validate);File.WriteAllText(path,text);output.Validate();File.Delete(path);Assert.Throws<IOException>(output.Validate);File.WriteAllText(path,text);File.WriteAllText(Path.Combine(output.DirectoryPath,"unexpected.stp"),"extra");Assert.Throws<IOException>(output.Validate);});
 [Fact]public void PrivateSchemaAndPrecisionDifferWithoutChangingOtherExportResult()=>WithSource((root,source,context)=>{var selected=context.GetLabel(source.Diagnostics.FreeRoots[0].Entry);var a=LocalStepAssemblyExport.Export(context,[selected],Path.Combine(root,"ap203"),new(LocalStepExportSchema.Ap203,LocalStepExportModes.Names,1e-5));var b=LocalStepAssemblyExport.Export(context,[selected],Path.Combine(root,"ap214"),new(LocalStepExportSchema.Ap214,LocalStepExportModes.All,1e-3));Assert.Equal(1e-5,a.AppliedOptions.Precision);Assert.Equal(1e-3,b.AppliedOptions.Precision);Assert.All(a.Files,x=>Assert.Contains("CONFIG_CONTROL_DESIGN",File.ReadAllText(Path.Combine(a.DirectoryPath,x.FileName)),StringComparison.Ordinal));Assert.All(b.Files,x=>Assert.Contains("AUTOMOTIVE_DESIGN",File.ReadAllText(Path.Combine(b.DirectoryPath,x.FileName)),StringComparison.Ordinal));a.Validate();b.Validate();});
 [Fact]public void ClosedSourceRejectsBeforeCreatingPublishedOrPrivateStage()=>WithSource((root,source,context)=>{var label=context.GetLabel(source.Diagnostics.FreeRoots[0].Entry);source.Dispose();string target=Path.Combine(root,"closed");Assert.Throws<ObjectDisposedException>(()=>LocalStepAssemblyExport.Export(context,[label],target));Assert.False(Directory.Exists(target));});
}
